 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    # Three-color tasks: the sparse signal color defines rays; bars are unchanged.
    marker = min((c for c in colors if c != bg), key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    # For each signal pixel, extend a ray in direction(s) indicated by matching
    # background-colored edge bars: horizontal and/or vertical rays, ending before
    # the far edge marker/bar. The endpoint changes to marker+1.
    # The demos show each isolated marker ray extends to the nearest boundary,
    # stopping immediately before the boundary stripe; original markers transform.
    special = next((c for c in colors if c not in (bg, marker)), None)
    if special is None:
        special = (marker + 1) % 10
    # Determine stripe lines (non-bg runs on outer edge) as barriers.
    edges = []
    for r in (0, h-1):
        cols = [c for c in range(w) if grid[r][c] != bg]
        if cols: edges.append(('h', r, min(cols), max(cols)))
    for c in (0, w-1):
        rows = [r for r in range(h) if grid[r][c] != bg]
        if rows: edges.append(('v', c, min(rows), max(rows)))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker: continue
            out[r][c] = special
            # rays toward edges whose stripe aligns with this coordinate
            for axis, edge, lo, hi in edges:
                if axis == 'h' and lo <= c <= hi:
                    step = -1 if edge == 0 else 1
                    rr = r + step
                    while 0 <= rr < h and grid[rr][c] == bg:
                        out[rr][c] = marker
                        rr += step
                elif axis == 'v' and lo <= r <= hi:
                    step = -1 if edge == 0 else 1
                    cc = c + step
                    while 0 <= cc < w and grid[r][cc] == bg:
                        out[r][cc] = marker
                        cc += step
    return out
